lower_chars(Chars) ->
    [client_simple_fold(Char)
     || Char
            <- lists:flatten([unicode_util:lowercase([C])
                              || C <- lists:flatten(Chars)])].

normalise_token(Token0, Opts) ->
    Lower =
        unicode:characters_to_binary(lower_chars(unicode_chars(Token0)),
                                     utf8),
    case maps:get(remove_diacritics, Opts, false) of
        false -> Lower;
        0 -> Lower;
        true -> strip_diacritics(Lower, 1);
        1 -> strip_diacritics(Lower, 1);
        2 -> strip_diacritics(Lower, 2)
    end.

remove_diacritics_enabled(Opts) ->
    case maps:get(remove_diacritics, Opts, false) of
        false -> false;
        0 -> false;
        _ -> true
    end.

sqlite_diacritic_mark(Char)
    when Char >= 768, Char =< 817 ->
    Offset = Char - 768,
    {Mask, Bit} = case Offset < 32 of
                      true -> {134389727, Offset};
                      false -> {221688, Offset - 32}
                  end,
    Mask band (1 bsl Bit) =/= 0;
sqlite_diacritic_mark(_Char) -> false.

sqlite_fold_diacritic(Char, _Mode)
    when Char >= 768, Char =< 879 ->
    case sqlite_diacritic_mark(Char) of
        true -> [];
        false -> [Char]
    end;
sqlite_fold_diacritic(Char, Mode) ->
    Decomposed = lists:flatten(unicode_util:nfd([Char])),
    case Decomposed of
        [Base | Marks]
            when Base >= $a andalso Base =< $z orelse
                     Base >= $A andalso Base =< $Z ->
            Removable = [M || M <- Marks, sqlite_diacritic_mark(M)],
            case {Mode,
                  length(Removable),
                  length(Removable) =:= length(Marks)}
                of
                {_Any, 0, _} -> [Char];
                {1, N, true} when N > 1 -> [Char];
                {_Any, _N, true} -> [Base];
                {_Any, _N, false} ->
                    [Base | [M || M <- Marks, not sqlite_diacritic_mark(M)]]
            end;
        _ -> [Char]
    end.

strip_diacritics(Token, Mode) ->
    Kept = lists:append([sqlite_fold_diacritic(Char, Mode)
                         || Char <- lists:flatten(unicode_chars(Token))]),
    unicode:characters_to_nfc_binary(Kept).

token_char(Char, Opts) ->
    TokenChars = maps:get(tokenchars, Opts, []),
    Separators = maps:get(separators, Opts, []),
    (unicode_token_char(Char, Opts) orelse
         lists:member(Char, TokenChars))
        andalso not lists:member(Char, Separators).

token_start(undefined, Offset) -> Offset;
token_start(Start, _Offset) -> Start.

tokenize_with_offsets(Text, Opts)
    when is_binary(Text), is_map(Opts) ->
    Stopwords = maps:get(stopwords, Opts, []),
    Tokens = case maps:get(tokenchars, Opts, []) =:= []
                      andalso maps:get(separators, Opts, []) =:= []
                 of
                 true ->
                     fast_tokens_with_offsets(Text,
                                              0,
                                              Opts,
                                              Stopwords,
                                              <<>>,
                                              false,
                                              undefined,
                                              0,
                                              []);
                 false ->
                     unicode_tokens_with_offsets(Text,
                                                 0,
                                                 Opts,
                                                 Stopwords,
                                                 <<>>,
                                                 undefined,
                                                 0,
                                                 [])
             end,
    [compat_source_range(Text, Token) || Token <- Tokens].

unicode_chars(Bin) when is_binary(Bin) ->
    case unicode:characters_to_list(Bin, utf8) of
        {error, Good, <<_Bad, Rest/binary>>} ->
            Good ++ unicode_chars(Rest);
        {error, Good, _Rest} -> Good;
        {incomplete, Good, _Rest} -> Good;
        Chars -> Chars
    end;
unicode_chars(List) when is_list(List) ->
    case unicode:characters_to_list(List, utf8) of
        {error, Good, [_Bad | Rest]} ->
            Good ++ unicode_chars(Rest);
        {error, Good, _Rest} -> Good;
        {incomplete, Good, _Rest} -> Good;
        Chars -> Chars
    end.

unicode_offset_char(CP, Char, Rest, Offset, NextOffset,
                    Opts, SW, Tok, Start, Pos, Acc) ->
    case token_char(CP, Opts) of
        true ->
            unicode_tokens_with_offsets(Rest,
                                        NextOffset,
                                        Opts,
                                        SW,
                                        <<Tok/binary, Char/binary>>,
                                        token_start(Start, Offset),
                                        Pos,
                                        Acc);
        false ->
            {Pos1, Acc1} = unicode_offset_flush(Tok,
                                                Start,
                                                Offset,
                                                Opts,
                                                SW,
                                                Pos,
                                                Acc),
            unicode_tokens_with_offsets(Rest,
                                        NextOffset,
                                        Opts,
                                        SW,
                                        <<>>,
                                        undefined,
                                        Pos1,
                                        Acc1)
    end.

unicode_offset_flush(<<>>, _Start, _End, _Opts, _SW,
                     Pos, Acc) ->
    {Pos, Acc};
unicode_offset_flush(Tok, Start, End, Opts, SW, Pos,
                     Acc) ->
    Norm = normalise_token(Tok, Opts),
    case {Norm =:= <<>>, lists:member(Norm, SW)} of
        {true, _} -> {Pos, Acc};
        {false, true} -> {Pos + 1, Acc};
        {false, false} ->
            {Pos + 1, [{Norm, Pos, Start, End - Start} | Acc]}
    end.

unicode_token_char(Char, Opts) ->
    case fts5_token_char(Char) of
        true -> true;
        false ->
            remove_diacritics_enabled(Opts) andalso
                sqlite_diacritic_mark(Char)
    end.

unicode_tokens_with_offsets(<<240, 159, 146, Next,
                              Rest/binary>>,
                            Offset, Opts, SW, Tok, Start, Pos, Acc)
    when Next band 192 =/= 128 ->
    unicode_offset_char(2002,
                        <<223, 146>>,
                        <<Next, Rest/binary>>,
                        Offset,
                        Offset + 3,
                        Opts,
                        SW,
                        Tok,
                        Start,
                        Pos,
                        Acc);
unicode_tokens_with_offsets(<<CP/utf8, Rest/binary>> =
                                Bin,
                            Offset, Opts, SW, Tok, Start, Pos, Acc) ->
    CharLen = byte_size(Bin) - byte_size(Rest),
    <<Char:CharLen/binary, _/binary>> = Bin,
    unicode_offset_char(CP,
                        Char,
                        Rest,
                        Offset,
                        Offset + CharLen,
                        Opts,
                        SW,
                        Tok,
                        Start,
                        Pos,
                        Acc);
unicode_tokens_with_offsets(<<_Bad, Rest/binary>>,
                            Offset, Opts, SW, Tok, Start, Pos, Acc) ->
    {Pos1, Acc1} = unicode_offset_flush(Tok,
                                        Start,
                                        Offset,
                                        Opts,
                                        SW,
                                        Pos,
                                        Acc),
    unicode_tokens_with_offsets(Rest,
                                Offset + 1,
                                Opts,
                                SW,
                                <<>>,
                                undefined,
                                Pos1,
                                Acc1);
unicode_tokens_with_offsets(<<>>, Offset, Opts, SW, Tok,
                            Start, Pos, Acc) ->
    {_Pos1, Acc1} = unicode_offset_flush(Tok,
                                         Start,
                                         Offset,
                                         Opts,
                                         SW,
                                         Pos,
                                         Acc),
    lists:reverse(Acc1).
